#!/usr/bin/env bash
# One-off clean-up of the fork (prepared by Claude, 2026-10-18). Run from the Actions tab:
# "Clean up fork branches (one-off)". Without APPLY it only prints what it would do.
set -euo pipefail
mode="${1:-show}"
git fetch --quiet origin "+refs/heads/*:refs/remotes/origin/*" "+refs/tags/*:refs/tags/*"
echo "== 1. Archive tags (branches that were never merged keep their commits as tags)"
if git ls-remote --exit-code --tags origin "refs/tags/archive/living-world/trade-sim" >/dev/null; then echo "  exists  archive/living-world/trade-sim"; else echo "  tag     archive/living-world/trade-sim -> b815378132fe"; if [ "$mode" = APPLY ]; then git tag -f "archive/living-world/trade-sim" b815378132fed3f3c935d000dc37b54652cc6737 && git push --quiet origin "refs/tags/archive/living-world/trade-sim"; fi; fi
if git ls-remote --exit-code --tags origin "refs/tags/archive/living-world/roadmap" >/dev/null; then echo "  exists  archive/living-world/roadmap"; else echo "  tag     archive/living-world/roadmap -> a6dc1f111855"; if [ "$mode" = APPLY ]; then git tag -f "archive/living-world/roadmap" a6dc1f11185501e13607fc52c43d1d49b906ae93 && git push --quiet origin "refs/tags/archive/living-world/roadmap"; fi; fi
if git ls-remote --exit-code --tags origin "refs/tags/archive/newclient/agx-tonemap" >/dev/null; then echo "  exists  archive/newclient/agx-tonemap"; else echo "  tag     archive/newclient/agx-tonemap -> 19ec6666d8fa"; if [ "$mode" = APPLY ]; then git tag -f "archive/newclient/agx-tonemap" 19ec6666d8faa7e73aa028f530a25c98b01d4708 && git push --quiet origin "refs/tags/archive/newclient/agx-tonemap"; fi; fi
if git ls-remote --exit-code --tags origin "refs/tags/archive/docs/readme-hook" >/dev/null; then echo "  exists  archive/docs/readme-hook"; else echo "  tag     archive/docs/readme-hook -> 5a37bbc896e8"; if [ "$mode" = APPLY ]; then git tag -f "archive/docs/readme-hook" 5a37bbc896e8a17dc95b90d0c1c2754efa4c1c62 && git push --quiet origin "refs/tags/archive/docs/readme-hook"; fi; fi
if git ls-remote --exit-code --tags origin "refs/tags/archive/feature/bot-personalities" >/dev/null; then echo "  exists  archive/feature/bot-personalities"; else echo "  tag     archive/feature/bot-personalities -> 7c9f97766440"; if [ "$mode" = APPLY ]; then git tag -f "archive/feature/bot-personalities" 7c9f97766440b698d015f7581c4080a26aa4f8c9 && git push --quiet origin "refs/tags/archive/feature/bot-personalities"; fi; fi
if git ls-remote --exit-code --tags origin "refs/tags/archive/ci/github-actions" >/dev/null; then echo "  exists  archive/ci/github-actions"; else echo "  tag     archive/ci/github-actions -> 751556bc6fce"; if [ "$mode" = APPLY ]; then git tag -f "archive/ci/github-actions" 751556bc6fce1b40f47357d34c4d27515ee08c6f && git push --quiet origin "refs/tags/archive/ci/github-actions"; fi; fi
if git ls-remote --exit-code --tags origin "refs/tags/archive/upstream-offer/bot-guilds" >/dev/null; then echo "  exists  archive/upstream-offer/bot-guilds"; else echo "  tag     archive/upstream-offer/bot-guilds -> 35ba71a4b321"; if [ "$mode" = APPLY ]; then git tag -f "archive/upstream-offer/bot-guilds" 35ba71a4b321b0904d98cb934b3da8566de68c3d && git push --quiet origin "refs/tags/archive/upstream-offer/bot-guilds"; fi; fi
if git ls-remote --exit-code --tags origin "refs/tags/archive/upstream-offer/xp-by-level" >/dev/null; then echo "  exists  archive/upstream-offer/xp-by-level"; else echo "  tag     archive/upstream-offer/xp-by-level -> e380ff9102a1"; if [ "$mode" = APPLY ]; then git tag -f "archive/upstream-offer/xp-by-level" e380ff9102a1bad9b9af4beb4bfe44aec8e0f938 && git push --quiet origin "refs/tags/archive/upstream-offer/xp-by-level"; fi; fi
if git ls-remote --exit-code --tags origin "refs/tags/archive/upstream-offer/social-expansion" >/dev/null; then echo "  exists  archive/upstream-offer/social-expansion"; else echo "  tag     archive/upstream-offer/social-expansion -> cad3f16709ed"; if [ "$mode" = APPLY ]; then git tag -f "archive/upstream-offer/social-expansion" cad3f16709eda689b509a47e5b255caea794673e && git push --quiet origin "refs/tags/archive/upstream-offer/social-expansion"; fi; fi
if git ls-remote --exit-code --tags origin "refs/tags/v0.36-se.2" >/dev/null; then echo "  exists  v0.36-se.2"; else echo "  tag     v0.36-se.2 -> 628e48bba86d"; if [ "$mode" = APPLY ]; then git tag -f "v0.36-se.2" 628e48bba86dc7c4df371818e814afadded358f1 && git push --quiet origin "refs/tags/v0.36-se.2"; fi; fi
if git ls-remote --exit-code --tags origin "refs/tags/v0.36-se.3" >/dev/null; then echo "  exists  v0.36-se.3"; else echo "  tag     v0.36-se.3 -> 888842acb911"; if [ "$mode" = APPLY ]; then git tag -f "v0.36-se.3" 888842acb91155928c172964134b727b6f4974b6 && git push --quiet origin "refs/tags/v0.36-se.3"; fi; fi
echo "== 2. Delete branches (merged into main, replaced by offer-0.37/*, or archived above)"
for b in claude-push-test-20261011 docs/audit-fixes docs/readme-living-server docs/readme-social-expansion feature/bot-guilds feature/bot-voices feature/launcher-tab feature/living-server feature/xp-by-level-range fix/bot-guild-cleanup fix/client-follow-buttons fix/meetup-deaths fix/runtime-audit integration/next living-world/living-server-backlog release/0.35-chris.1 release/0.36-chris.1 release/0.36-chris.2 release/0.36-chris.3 release/0.36-chris.4 release/0.36-chris.5 release/0.36-chris.6 release/0.36-chris.7 release/0.36-chris.8 release/0.36-chris.9 release/0.36-chris.11 release/0.36-se.1 release/0.36-se.2 release/0.36-se.3 sync/upstream-0.36 feature/voices-se4 fix/se3-chat-logging docs/se4-line-count se4-live-test-fixes upstream-fix/dead-bot-corpse upstream-fix/meetup-death-cap upstream-fix/newclient-server-target upstream-fix/newclient-target-buttons upstream-offer/bot-guilds upstream-offer/xp-by-level upstream-offer/social-expansion ci/upstream-fixes-check reconcile-0.37 fix/037-install-detection docs/037-real-upgrade living-world/trade-sim living-world/roadmap newclient/agx-tonemap docs/readme-hook feature/bot-personalities ci/github-actions chore/cleanup-workflow; do
  if ! git rev-parse -q --verify "refs/remotes/origin/$b" >/dev/null; then echo "  gone    $b"; continue; fi
  case "$b" in main|offer-0.37/*) echo "  KEEP    $b"; continue;; esac
  tip=$(git rev-parse "refs/remotes/origin/$b")
  echo "  delete  $b ($(git log -1 --format=%h "$tip"))"
  if [ "$mode" = APPLY ]; then git push --quiet origin --delete "$b"; fi
done
echo "== Left on the fork:"; git ls-remote --heads origin | sed "s#.*refs/heads/#  #"
[ "$mode" = APPLY ] || echo "Nothing was changed. Run it again with APPLY to do it."
